import test from 'node:test';
import assert from 'node:assert/strict';
import {morphGAC} from '../src/browser-active-contours.js';

// Golden output generated by scikit-image revision
// 533b7694d2004ae84e49e2cfd0bcfc5f8e562f22.
test('browser MorphGAC exactly matches scikit-image on analytic edge-stop fixture',()=>{
  const n=48,w=n,h=n,gimage=new Float32Array(n*n),init=new Uint8Array(n*n);
  for(let y=0;y<n;y++)for(let x=0;x<n;x++){
    const r=Math.hypot(x-24,y-23);
    gimage[y*n+x]=.08+.92*(1-Math.exp(-((r-12)**2)/(2*1.6**2)));
    init[y*n+x]=r<16?1:0;
  }
  const rle=[[0,596],[1,9],[0,37],[1,13],[0,34],[1,15],[0,32],[1,17],[0,30],[1,19],[0,28],[1,21],[0,27],[1,21],[0,26],[1,23],[0,25],[1,23],[0,25],[1,23],[0,25],[1,23],[0,25],[1,23],[0,25],[1,23],[0,25],[1,23],[0,25],[1,23],[0,25],[1,23],[0,26],[1,21],[0,27],[1,21],[0,28],[1,19],[0,30],[1,17],[0,32],[1,15],[0,34],[1,13],[0,37],[1,9],[0,643]];
  const golden=[];
  for(const [v,count] of rle)for(let i=0;i<count;i++)golden.push(v);
  const out=morphGAC(gimage,w,h,init,{numIter:50,smoothing:1,threshold:'auto',balloon:-1});
  assert.equal(out.length,golden.length);
  let diff=0;
  for(let i=0;i<out.length;i++)diff+=out[i]!==golden[i];
  assert.equal(diff,0);
});
